file.content:
/* Page sections. Each block is used by the page named in its comment. */

/* Home */

.hero {
  position: relative;
  overflow: hidden;
  padding: var(--space-8) 0 calc(var(--space-8) + 56px);
  border-bottom: 1px solid var(--color-line);
  background: linear-gradient(180deg, var(--color-brand-tint), var(--color-bg));
}

.hero::before {
  content: '';
  position: absolute;
  top: -140px;
  right: -100px;
  width: 460px;
  height: 460px;
  border-radius: 50%;
  background: radial-gradient(closest-side, rgba(6, 182, 212, 0.2), rgba(6, 182, 212, 0));
}

.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 420px;
  gap: var(--space-7);
  align-items: center;
}

.hero-copy h1 {
  font-size: 44px;
}

.hero-copy .lede {
  max-width: 480px;
  margin-top: var(--space-4);
}

.hero-actions {
  display: flex;
  gap: var(--space-3);
  margin-top: var(--space-5);
}

.stats-overlap {
  position: relative;
  z-index: 1;
  margin-top: -56px;
}

.feature {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: var(--space-6);
  align-items: center;
  overflow: hidden;
}

.feature-art {
  height: 260px;
  background: linear-gradient(135deg, #0ea5e9, #6366f1);
}

.feature-copy {
  padding: var(--space-5) var(--space-5) var(--space-5) 0;
}

.feature-copy h3 {
  font-size: 22px;
}

.feature-copy .price {
  margin: var(--space-3) 0 var(--space-4);
}

.newsletter {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-6);
  align-items: center;
  padding: var(--space-6);
}

.form-note {
  margin-top: var(--space-2);
  font-size: 13px;
}

/* Products */

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-bottom: var(--space-5);
}

.chip {
  padding: 6px 14px;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-pill);
  background: var(--color-surface);
  font-size: 14px;
  font-weight: 600;
  color: var(--color-muted);
}

.chip.is-active {
  border-color: var(--color-ink);
  background: var(--color-ink);
  color: #ffffff;
}

.thumb-1 {
  background: linear-gradient(135deg, #0ea5e9, #6366f1);
}

.thumb-2 {
  background: linear-gradient(135deg, #f59e0b, #ef4444);
}

.thumb-3 {
  background: linear-gradient(135deg, #10b981, #0e7490);
}

.thumb-4 {
  background: linear-gradient(135deg, #a855f7, #ec4899);
}

.thumb-5 {
  background: linear-gradient(135deg, #64748b, #0f172a);
}

.thumb-6 {
  background: linear-gradient(135deg, #facc15, #84cc16);
}

.bundles {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-5);
}

/* Pricing */

.plans {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-5);
  align-items: start;
  padding-top: var(--space-4);
}

.plan {
  position: relative;
  padding: var(--space-5);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-lg);
  background: var(--color-surface);
}

.plan-featured {
  border: 2px solid var(--color-brand);
  box-shadow: var(--shadow-md);
}

.plan-ribbon {
  position: absolute;
  top: -13px;
  left: 50%;
  z-index: 1;
  padding: 3px 12px;
  border-radius: var(--radius-pill);
  background: var(--color-brand);
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
  transform: translateX(-50%);
}

.plan-price {
  margin: var(--space-3) 0;
  font-size: 40px;
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.plan-price small {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0;
  color: var(--color-muted);
}

.plan-features {
  margin: var(--space-4) 0 var(--space-5);
}

.plan-features li {
  padding: var(--space-2) 0;
  border-top: 1px solid var(--color-line);
  font-size: 15px;
}

.plan .btn {
  width: 100%;
}

.faq {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-5);
}

.faq-item h3 {
  margin-bottom: var(--space-2);
}

.faq-item p {
  font-size: 15px;
  color: var(--color-muted);
}

/* Orders */

.table-tools {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: var(--space-4);
  font-size: 14px;
  color: var(--color-muted);
}

.pager {
  display: flex;
  gap: var(--space-2);
}

/* Contact */

.contact-grid {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: var(--space-6);
  align-items: start;
}

.info-list dt {
  margin-top: var(--space-4);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--color-muted);
}

.info-list dt:first-child {
  margin-top: 0;
}

.info-list dd {
  overflow-wrap: anywhere;
}

/* About */

.story {
  display: grid;
  grid-template-columns: 1fr 480px;
  gap: var(--space-7);
  align-items: center;
}

.story p + p {
  margin-top: var(--space-4);
}

.story-art {
  border-radius: var(--radius-lg);
}

.avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin-bottom: var(--space-3);
  border-radius: 50%;
  background: var(--color-brand-tint);
  font-size: 18px;
  font-weight: 800;
  color: var(--color-brand-dark);
}

.timeline {
  padding-left: var(--space-5);
  border-left: 2px solid var(--color-line);
}

.timeline-item {
  position: relative;
  padding-bottom: var(--space-5);
}

.timeline-item:last-child {
  padding-bottom: 0;
}

.timeline-item::before {
  content: '';
  position: absolute;
  top: 5px;
  left: -32px;
  width: 12px;
  height: 12px;
  border: 2px solid var(--color-surface);
  border-radius: 50%;
  background: var(--color-brand);
}

.timeline-year {
  font-weight: 800;
  color: var(--color-brand);
}

.cta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-5);
  padding: var(--space-6);
  border-radius: var(--radius-lg);
  background: var(--color-ink);
  color: #ffffff;
}

.cta p {
  margin-top: var(--space-1);
  color: #c9d1d9;
}

@media (max-width: 720px) {
  .hero {
    padding-top: var(--space-7);
  }

  .hero-inner,
  .feature,
  .newsletter,
  .bundles,
  .plans,
  .faq,
  .contact-grid,
  .story {
    grid-template-columns: 1fr;
  }

  .hero-copy h1 {
    font-size: 32px;
  }

  .feature-copy {
    padding: 0 var(--space-5) var(--space-5);
  }

  .feature-art {
    height: 160px;
  }

  .newsletter {
    padding: var(--space-5);
  }

  .cta {
    flex-direction: column;
    align-items: flex-start;
  }
}

content.content:
1	/* Shared components: header, button, card, form, table, modal, and friends. */
2	
3	/* Header */
4	
5	.site-header {
6	  position: sticky;
7	  top: 0;
8	  z-index: 100;
9	  background: var(--color-surface);
10	  border-bottom: 1px solid var(--color-line);
11	}
12	
13	.header-inner {
14	  display: flex;
15	  align-items: center;
16	  justify-content: space-between;
17	  height: var(--header-height);
18	}
19	
20	.brand {
21	  display: flex;
22	  align-items: center;
23	  gap: var(--space-2);
24	  font-size: 18px;
25	  font-weight: 800;
26	  color: var(--color-ink);
27	  text-decoration: none;
28	}
29	
30	.site-nav {
31	  display: flex;
32	  gap: var(--space-1);
33	}
34	
35	.nav-link {
36	  padding: var(--space-2) var(--space-3);
37	  border-radius: var(--radius-sm);
38	  font-size: 15px;
39	  font-weight: 600;
40	  color: var(--color-ink);
41	  text-decoration: none;
42	}
43	
44	.nav-link:hover {
45	  background: var(--color-bg);
46	}
47	
48	.nav-link[aria-current='page'] {
49	  color: var(--color-brand);
50	  background: var(--color-brand-tint);
51	}
52	
53	.nav-toggle {
54	  display: none;
55	  width: 40px;
56	  height: 40px;
57	  padding: 0;
58	  border: 1px solid var(--color-line);
59	  border-radius: var(--radius-sm);
60	  background: var(--color-surface);
61	  cursor: pointer;
62	}
63	
64	.nav-toggle-bar {
65	  display: block;
66	  width: 18px;
67	  height: 2px;
68	  margin: 4px auto;
69	  border-radius: 1px;
70	  background: var(--color-ink);
71	}
72	
73	/* Button */
74	
75	.btn {
76	  display: inline-flex;
77	  align-items: center;
78	  justify-content: center;
79	  padding: 10px 18px;
80	  border: 1px solid transparent;
81	  border-radius: var(--radius-md);
82	  font: inherit;
83	  font-size: 15px;
84	  font-weight: 700;
85	  line-height: 1.2;
86	  text-decoration: none;
87	  cursor: pointer;
88	}
89	
90	.btn-primary {
91	  background: var(--color-brand);
92	  color: #ffffff;
93	}
94	
95	.btn-primary:hover {
96	  background: var(--color-brand-dark);
97	}
98	
99	.btn-secondary {
100	  background: var(--color-surface);
101	  color: var(--color-ink);
102	  border-color: var(--color-line);
103	}
104	
105	.btn-secondary:hover {
106	  background: var(--color-bg);
107	}
108	
109	.btn-sm {
110	  padding: 6px 12px;
111	  border-radius: var(--radius-sm);
112	  font-size: 13px;
113	}
114	
115	.btn-lg {
116	  padding: 13px 24px;
117	  font-size: 16px;
118	}
119	
120	.btn[disabled] {
121	  opacity: 0.5;
122	  cursor: not-allowed;
123	}
124	
125	/* Card */
126	
127	.card {
128	  position: relative;
129	  overflow: hidden;
130	  background: var(--color-surface);
131	  border: 1px solid var(--color-line);
132	  border-radius: var(--radius-lg);
133	  box-shadow: var(--shadow-sm);
134	}
135	
136	.card-body {
137	  padding: var(--space-5);
138	}
139	
140	.card-thumb {
141	  height: 120px;
142	  border-radius: 13px 13px 0 0;
143	}
144	
145	.card h3 {
146	  margin-bottom: var(--space-2);
147	}
148	
149	.card p {
150	  font-size: 15px;
151	  color: var(--color-muted);
152	}
153	
